import{c as t,Q as o,j as d,m as r}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Harness v5.1 單人化精簡 — 完整刪除報告","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-08-02-harness-v5.1-simplification.md","filePath":"research/reports/2026-08-02-harness-v5.1-simplification.md","lastUpdated":1785909234000}'),a={name:"research/reports/2026-08-02-harness-v5.1-simplification.md"};function s(c,e,n,i,h,l){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="harness-v5-1-單人化精簡-—-完整刪除報告" tabindex="-1">Harness v5.1 單人化精簡 — 完整刪除報告 <a class="header-anchor" href="#harness-v5-1-單人化精簡-—-完整刪除報告" aria-label="Permalink to &quot;Harness v5.1 單人化精簡 — 完整刪除報告&quot;">​</a></h1><blockquote><p><strong>日期</strong>：2026-08-02 · <strong>分支</strong>：<code>claude/harness-simplification-ti7hkd</code> · <strong>主 commit</strong>：<code>3c3566f</code>（115 檔、+258/−8,283 行） <strong>決策鏈</strong>：使用者裁決「v5 over-design，單人 workspace 不需團隊級防禦」→ Fable 5 統籌 → Opus 5（架構/風險視角）+ Sonnet 5（日常成本/摩擦視角）獨立分析 → Fable 5 合成裁決並執行。 <strong>驗證收據</strong>：<code>bash scripts/healthcheck.sh</code> → <strong>PASS 200 / WARN 0 / FAIL 0</strong>；<code>check-anchors</code> stale=0；<code>check-references</code> dangling=0 orphan=0；<code>check-section-refs</code> 43 筆全可解析；<code>measure.sh --gate</code> PASS。</p></blockquote><hr><h2 id="_0-核心診斷-失衡不在「防禦太多」-在「自指性太高」" tabindex="-1">0. 核心診斷：失衡不在「防禦太多」，在「自指性太高」 <a class="header-anchor" href="#_0-核心診斷-失衡不在「防禦太多」-在「自指性太高」" aria-label="Permalink to &quot;0. 核心診斷：失衡不在「防禦太多」，在「自指性太高」&quot;">​</a></h2><p>兩個分析視角收斂到同一結論：v5 的問題不是防線本身，而是<strong>系統長出了大量維護自己的機制</strong>。116 支 scripts 裡約 40 支在量測/驗證 harness 自己；26 個 refs 裡近半是「規則的規則」（enforcement manifest、句級 clause map、<code>[E*]</code> 缺口清單）；26 個 hooks 裡 13 個服務的對象是「多人需要對規則有共同認知」或「parent 不信任 child agent」的組織場景。</p><p>「單人 workspace」消掉的是<strong>人與人之間的不信任</strong>（review 收據、branch protection、契約稽核、審計留痕）。它<strong>沒有</strong>消掉「LLM 輸出不可信」——sub-agent 仍會虛報、模型仍會 reward-hack 測試、外部輸入仍是注入面。因此刀口是三分：</p><ul><li><strong>砍元層</strong>：管理 harness 的 harness（enforcement-manifest、<code>[E*]</code> 分類學、clause manifest、mutation audit）</li><li><strong>砍協作層</strong>：人對人的信任機制（收據、契約欄位 lint、審計 log、branch 互搶防護）</li><li><strong>留執行層</strong>：與人數無關的真防線（不可逆操作攔截、reward hacking 防線、敏感檔保護、外部注入防護、容器遺失防護）</li></ul><hr><h2 id="_1-hooks-26-→-13-刪-13-支" tabindex="-1">1. Hooks：26 → 13（刪 13 支） <a class="header-anchor" href="#_1-hooks-26-→-13-刪-13-支" aria-label="Permalink to &quot;1. Hooks：26 → 13（刪 13 支）&quot;">​</a></h2><h3 id="_1-1-刪除清單與逐支理由" tabindex="-1">1.1 刪除清單與逐支理由 <a class="header-anchor" href="#_1-1-刪除清單與逐支理由" aria-label="Permalink to &quot;1.1 刪除清單與逐支理由&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hook</th><th>掛載點</th><th>刪除理由（深入）</th></tr></thead><tbody><tr><td><code>pre-commit-review.sh</code></td><td>PreToolUse[Bash]</td><td>自承判定邏輯已於 2026-07-31 下沉至 <code>.githooks/pre-commit</code>，本層只剩「早回饋」。其守護的<strong>尺寸門檻（5 檔/200 行）+ review 收據制度</strong>存在的前提是「超大 commit 會傷害 reviewer 的 PR review 語義」——單人 repo 沒有 reviewer，你就是核可者，收據是自己發給自己的形式主義</td></tr><tr><td><code>branch-isolation-guard.sh</code></td><td>PreToolUse[Bash]</td><td>防「多 session 共用 worktree 分支互搶」。LESSONS 曾有單日 6 次重現紀錄（真陽性有據），但那是多視窗並行時代的產物；遠端容器環境一 session 一容器，互搶前提消失。只 warn 不 block、可自 git 歷史還原</td></tr><tr><td><code>handoff-return-check.sh</code></td><td>PostToolUse[Agent]</td><td>機械檢查 sub-agent Return 五欄（達標?/驗證輸出/open_questions/偏離說明/升級建議）是否齊備。這是給「不信任 child 又不想讀 child 全文」的組織用的；單人 parent 直接讀 sub-agent 回覆，欄位齊不齊一眼可見。其呼叫的 <code>validate-handoff-return.sh</code> 一併刪除</td></tr><tr><td><code>taste-reference-lint.sh</code></td><td>UserPromptSubmit + PreToolUse[Agent|Workflow]（雙掛載）</td><td>品味類請求缺 Reference 時的 advisory。防的是「你沒給 reference」——你自己知道自己有沒有給。lexical 比對天花板早經 F19 稽核證實（<code>TASTE_RE</code> 曾漏「專業一點」原句）；摩擦排名第一（雙掛載，頻率最高）</td></tr><tr><td><code>gate-widening-guard.sh</code></td><td>PreToolUse[Bash] + [Edit|Write]（雙掛載）</td><td>「閘門放寬=新攻擊面，須獨立對抗複審」提醒。防的是<strong>別人</strong>（或失控 agent）偷偷放寬權限；單人改自己的 settings.json，「獨立對抗複審」是自我對話。<code>e-star-body-gaps.md</code> 自己寫過「依強度不足移除它同樣合理」（誤報率 2/31、真陽性未證實）。本次精簡過程中它照常對每次 settings.json 編輯開火——即為摩擦實證</td></tr><tr><td><code>literal-specialcase-lint.sh</code></td><td>PostToolUse[Edit|Write]</td><td>掃字面特判模式（如 <code>n == 97</code>）的 advisory。F7 眼四輪連紅（0/3），證據面自承 lexical 掃描觸頂、換寫法即繞過。防 reward hacking 的真防線是 commit 時的 <code>test-integrity-guard</code>（保留），編輯當下的嘮叨是重複防線</td></tr><tr><td><code>test-file-redflag.sh</code></td><td>PostToolUse[Edit|Write]</td><td>「測試檔被編輯」即提醒的 advisory。與 <code>test-integrity-guard.sh</code>（保留，commit 時硬擋「混改 tests+src」）完全同軸，只是把攔截點前移到編輯當下——多一次每 Edit 的 process spawn 換一句遲早會在 commit 被攔的預告</td></tr><tr><td><code>pre-push-cost.sh</code></td><td>PreToolUse[Bash]</td><td>push 前寫 <code>evolution/cost-log.jsonl</code>。純記帳、無決策消費者——沒有任何流程讀這份 log 做決定。成本資訊平台側已有</td></tr><tr><td><code>audit-permission.sh</code></td><td>PermissionRequest</td><td>記錄 allow/deny 決策的審計留痕。審計的受眾是「事後要對第三者交代的組織」；單人無人看 permission log</td></tr><tr><td><code>usage-delegation-gate.sh</code></td><td>PreToolUse[Agent|Workflow]（timeout 20s，全表最重）</td><td>雙功能：①用量 gate——<code>CLAUDE_USAGE_GUARD_MODE=remind</code> 使其恆不阻斷，實質已死；②G4 契約欄位 lint——≥500B 派工 prompt 缺 Goal/Done-when/Return 即 <strong>block</strong>。後者正是本次任務開場擋掉合法委派的那支：單人寫 brief 缺一欄不該被硬擋。<strong>已知代價</strong>：刪除後無人值守 skill（overnight-research/autoresearch）失控 fan-out 只剩 <code>CLAUDE_USAGE_LIMIT_USD</code> 環境變數一道煞車（見 §7 風險）</td></tr><tr><td><code>memory-pr-record.sh</code></td><td>PostToolUse[mcp create_pull_request] + [Bash]（雙掛載，12KB 全表最大 advisory）</td><td>PR 建立後自動寫 MEMORY.md 的 PR 記錄。團隊交接語義；單人 repo 的 PR 是自己開給自己的，需要記就手動一行。E3 mutation test 曾抓到其 gh 路徑「註冊完整、註解齊全但從未生效」——存在 ≠ 生效的實證樣本</td></tr><tr><td><code>generator-ref-check.sh</code></td><td>PreToolUse[Bash]</td><td><code>git rm</code>/<code>mv</code> 前 grep 硬編碼引用的 advisory。立規依據是「一個 session 內重現 4 次」——單一連續事件，不符 core.md 自己的「同簽名跨 session ≥2 次才改規則」。其功能已被 <code>check-references.sh</code>（保留，healthcheck FAIL 級）事後閘覆蓋</td></tr><tr><td><code>tool-log.sh</code></td><td>PostToolUse[Bash] + PostToolUseFailure（雙掛載）</td><td>統一工具呼叫日誌。<code>command-log.jsonl</code> 僅 14 行＝幾乎無寫入亦無讀取消費；同步（非 async）掛載即每次 Bash 都付一次 spawn 延遲。純寫入無消費</td></tr></tbody></table><h3 id="_1-2-保留清單-13-支-與保留理由" tabindex="-1">1.2 保留清單（13 支）與保留理由 <a class="header-anchor" href="#_1-2-保留清單-13-支-與保留理由" aria-label="Permalink to &quot;1.2 保留清單（13 支）與保留理由&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hook</th><th>保留理由</th></tr></thead><tbody><tr><td><code>block-dangerous.sh</code>（41KB，43 fixtures）</td><td>唯一真正防不可逆損失的防線（rm -rf/terraform destroy/kubectl delete/git push --force/curl|sh）。單人一樣手滑。已知繞過面台帳（R1–R12）已自 hooks/INDEX.md 保留</td></tr><tr><td><code>test-integrity-guard.sh</code></td><td>reward hacking 是<strong>模型本性</strong>不是團隊問題，與人數無關。commit 時攔「混改 oracle 檔+非 oracle 檔」，成本近零。本次精簡 commit 它照常開火要求 <code>[tests-modified]</code> 說明——留著的價值當場自證</td></tr><tr><td><code>protect-sensitive-files.sh</code></td><td><code>.env</code>/credentials 誤編輯與人數無關</td></tr><tr><td><code>unicode-covert-channel-guard.sh</code></td><td>外部輸入（WebFetch/issue/PR body）的注入面與人數無關；確定性偵測、不阻斷、便宜</td></tr><tr><td><code>session-init.sh</code> / <code>session-end.sh</code> / <code>session-stop.sh</code> / <code>memory-sync.sh</code></td><td>遠端容器環境的地基：git pull、hooksPath 掛載、MEMORY 注入、容器回收前最後 push。單人<strong>更</strong>需要——沒有隊友幫你救回未 push 的變更</td></tr><tr><td><code>post-edit.sh</code></td><td>語法驗證（.sh/.json/.py）是最廉價的確定性檢查，「任何檔位永不跳過」</td></tr><tr><td><code>pre-compact.sh</code> / <code>post-compact.sh</code></td><td>compact 是真實會丟狀態的事件，單人長跑更常撞到</td></tr><tr><td><code>user-prompt-submit.sh</code></td><td>task-context 注入 + memory 狀態提示。體積大（23KB），內部段落級剪枝列為後續工作，本輪未動</td></tr></tbody></table><h3 id="_1-3-兩位分析者的分歧與裁決" tabindex="-1">1.3 兩位分析者的分歧與裁決 <a class="header-anchor" href="#_1-3-兩位分析者的分歧與裁決" aria-label="Permalink to &quot;1.3 兩位分析者的分歧與裁決&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>Opus 5</th><th>Sonnet 5</th><th>裁決</th></tr></thead><tbody><tr><td><code>tool-log.sh</code></td><td>留（telemetry 來源）</td><td>刪（14 行無消費者）</td><td><strong>刪</strong>——「有消費者才留 log」原則</td></tr><tr><td><code>unicode-covert-channel-guard</code></td><td>留</td><td>降級/低優先</td><td><strong>留</strong>——外部注入與人數無關</td></tr><tr><td><code>branch-isolation-guard</code></td><td>條件留（常開多視窗則留）</td><td>刪</td><td><strong>刪</strong>——遠端容器一 session 一容器</td></tr><tr><td><code>usage-delegation-gate</code></td><td>拆半：刪契約 lint、留預算 gate 並改 block</td><td>整支刪</td><td><strong>整支刪</strong>，風險記錄於 §7（可只還原預算半支）</td></tr></tbody></table><hr><h2 id="_2-refs-26-→-11-刪-15-個" tabindex="-1">2. Refs：26 → 11（刪 15 個） <a class="header-anchor" href="#_2-refs-26-→-11-刪-15-個" aria-label="Permalink to &quot;2. Refs：26 → 11（刪 15 個）&quot;">​</a></h2><h3 id="_2-1-enforcement-manifest-官僚層-3-檔-——v5-1-最大的結構性刪除" tabindex="-1">2.1 enforcement-manifest 官僚層（3 檔）——v5.1 最大的結構性刪除 <a class="header-anchor" href="#_2-1-enforcement-manifest-官僚層-3-檔-——v5-1-最大的結構性刪除" aria-label="Permalink to &quot;2.1 enforcement-manifest 官僚層（3 檔）——v5.1 最大的結構性刪除&quot;">​</a></h3><table tabindex="0"><thead><tr><th>檔</th><th>刪除理由</th></tr></thead><tbody><tr><td><code>enforcement-manifest.json</code></td><td><code>[E]</code> 宣稱→Body→註冊點→正反例→最近證據的機讀矩陣（build artifact）。維護鏈：改任何 hook → 重跑 <code>build-enforcement-manifest.py</code> → healthcheck <code>--check</code> 稽核 dormant。這整條鏈服務的是「多人對『這條規則有沒有牙齒』需要共同認知」；單人：你知道哪些有 hook</td></tr><tr><td><code>clause-body-map.json</code></td><td><strong>句級</strong> owner manifest——core.md 每一句都要登記自己是 P/E/E*，clause id 綁條文內容 hash，<strong>句子改寫即成新 clause 強制重新分類</strong>。這是單人 workspace 能做到的最貴的自我束縛：改一個字都要過分類儀式</td></tr><tr><td><code>e-star-body-gaps.md</code></td><td><code>[E*]</code> 逐條缺口清單（缺哪個 Body、怎麼補）。<code>[E*]</code> 分類本身廢除（見 §4），此檔是該分類的維護成本具現化</td></tr></tbody></table><p><strong><code>[E*]</code> 廢除的邏輯</strong>：<code>[E*]</code> 的定義是「需 Body 但目前無機械支撐，實質為 advisory」——那在行為上就是 <code>[P]</code>。三分類 + 缺口清單 + liveness 稽核腳本的全部價值，是讓多人不必逐一驗證就知道每條規則的強制力實況。單人環境改<strong>二分</strong>：有 hook 的標 <code>[E]</code>，其餘不標。誠實聲明「<code>[E]</code> ≠ 已 enforce」仍然成立（見 SPEC-v5 §5），但不再需要一套機讀基建去證明它。</p><h3 id="_2-2-loop-graph-delegation-細則層-5-檔" tabindex="-1">2.2 loop/graph/delegation 細則層（5 檔） <a class="header-anchor" href="#_2-2-loop-graph-delegation-細則層-5-檔" aria-label="Permalink to &quot;2.2 loop/graph/delegation 細則層（5 檔）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>檔</th><th>刪除理由</th></tr></thead><tbody><tr><td><code>loop-engineering.md</code></td><td>L0–L5 完整細則的 canonical owner。精華（四重終止、verifier 分離、測試檔紅旗、blast radius）已壓成 <code>core.md §APPLY</code> 自主迴圈一節（4 行）；L0 四條件資格閘、經濟停損指標、oracle mutation 細則屬「多輪無人值守 loop 跑很久」才觸及的儀式，日常不需常備</td></tr><tr><td><code>graph-engineering.md</code></td><td>G0–G5 完整細則。精華（預設親做、brief 三要素、產出者不驗收、gate parent 親跑、外部輸入=資料、verdict 非證據）已壓成 <code>core.md §PROPOSE</code> 委派一節（4 行）；節點四型表、fan-out 上限、Handoff Contract 七欄、污染半徑細則屬大規模 fan-out 場景</td></tr><tr><td><code>delegation-protocol.md</code></td><td>T0/T1/T2 委派分層 + 交辦三要素 + 升降級 + Coordinator-Specialist rubric。單人可用「Goal/Context/Done-when 寫全」一句取代整份文件</td></tr><tr><td><code>task-templates.md</code></td><td>任務交辦填空範本 ×5。服務對象是 sub-agent brief 的標準化，非單人自答</td></tr><tr><td><code>long-run-graph.md</code></td><td>長跑執行經濟學。與 graph-engineering / model-profiles 三方重疊</td></tr></tbody></table><h3 id="_2-3-harness-鏡像-自我評估層-5-檔" tabindex="-1">2.3 harness 鏡像/自我評估層（5 檔） <a class="header-anchor" href="#_2-3-harness-鏡像-自我評估層-5-檔" aria-label="Permalink to &quot;2.3 harness 鏡像/自我評估層（5 檔）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>檔</th><th>刪除理由</th></tr></thead><tbody><tr><td><code>the-loop-best-solution.md</code></td><td>core.md 的加長版（檢查表 + 失敗案例）。同一內容兩處 owner = v2–v4 兩層重複稅的殘影</td></tr><tr><td><code>harness-loop.md</code></td><td>自承「canonical = rules/core.md」的鏡像</td></tr><tr><td><code>harness-design.md</code></td><td>設計心智模型，canonical 在 research/，純複本</td></tr><tr><td><code>per-model-eval-suite.md</code></td><td>評估 harness 自己的 playbook（PGE 三相流程）。eval 基建已凍結擴張（2026-07-30 裁決），playbook 無執行場景</td></tr><tr><td><code>gap-validation-protocol.md</code></td><td>Gap 驗證協議，服務 gap-vote 多技能共識——harness 管 harness 的二階工具</td></tr></tbody></table><h3 id="_2-4-skill-schema-層-2-檔" tabindex="-1">2.4 skill schema 層（2 檔） <a class="header-anchor" href="#_2-4-skill-schema-層-2-檔" aria-label="Permalink to &quot;2.4 skill schema 層（2 檔）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>檔</th><th>刪除理由</th></tr></thead><tbody><tr><td><code>skill-gotcha-protocol.md</code></td><td>SKILL GOTCHAS 寫法 schema。28 skill 已定型，schema 的邊際價值歸零</td></tr><tr><td><code>pilot-shared-preflights.md</code></td><td>Pilot 共用 preflight。應內聯於 pilot SKILL，不值一個獨立 ref</td></tr></tbody></table><h3 id="_2-5-保留的-11-個-refs" tabindex="-1">2.5 保留的 11 個 refs <a class="header-anchor" href="#_2-5-保留的-11-個-refs" aria-label="Permalink to &quot;2.5 保留的 11 個 refs&quot;">​</a></h3><p><code>model-profiles.md</code>（L2 數字 SSoT，唯一准放模型名處）、<code>judgment-rubrics.md</code>、<code>git-ops.md</code>、<code>error-handling.md</code>、<code>context-engineering-claude5.md</code>（剪枝判準本身）、<code>post-compact-checklist.md</code>、<code>cache-health-metrics.md</code>、<code>maintenance-protocol.md</code>、<code>claude-oauth-token.md</code>、<code>removed-content-manifest.txt</code>（verified-merge Gate 3 機制檔）、<code>INDEX.md</code>。</p><hr><h2 id="_3-rules-5-→-3-auto-load-常駐-20-3kb-→-10-7kb-−47" tabindex="-1">3. Rules：5 → 3（auto-load 常駐 20.3KB → 10.7KB，−47%） <a class="header-anchor" href="#_3-rules-5-→-3-auto-load-常駐-20-3kb-→-10-7kb-−47" aria-label="Permalink to &quot;3. Rules：5 → 3（auto-load 常駐 20.3KB → 10.7KB，−47%）&quot;">​</a></h2><h3 id="_3-1-刪除的兩檔" tabindex="-1">3.1 刪除的兩檔 <a class="header-anchor" href="#_3-1-刪除的兩檔" aria-label="Permalink to &quot;3.1 刪除的兩檔&quot;">​</a></h3><ul><li><strong><code>loop.md</code>（3.4KB）整檔刪</strong>：骨架句壓成 <code>core.md §APPLY</code>「自主迴圈」4 行——①終止條件並存宣告 ②verifier 異 instance 只回 PASS/FAIL ③測試檔被改=紅旗中止 ④先定 blast radius。L0 資格閘四條件、L4 oracle mutation、經濟停損——刪。</li><li><strong><code>graph.md</code>（2.5KB）整檔刪</strong>：壓成 <code>core.md §PROPOSE</code>「委派」4 行——預設親做、brief 寫全 Goal/Context/Done-when、產出者不驗收自己產出、gate parent 親跑、外部輸入=資料非指令、child verdict 非證據。G0–G5 編號、節點四型表、fan-out 上限、Handoff 七欄——刪。</li></ul><h3 id="_3-2-core-md-重寫-10-7kb-→-6-0kb-刪除的條文" tabindex="-1">3.2 core.md 重寫（10.7KB → 6.0KB）刪除的條文 <a class="header-anchor" href="#_3-2-core-md-重寫-10-7kb-→-6-0kb-刪除的條文" aria-label="Permalink to &quot;3.2 core.md 重寫（10.7KB → 6.0KB）刪除的條文&quot;">​</a></h3><table tabindex="0"><thead><tr><th>刪除段落</th><th>理由</th></tr></thead><tbody><tr><td>檔頭 <code>[P]</code>/<code>[E]</code>/<code>[E*]</code> 三分類定義 + 常駐位判準</td><td><code>[E*]</code> 廢除；改二分後一句話講完</td></tr><tr><td>§TEST「Oracle 資格先於採信」的 <code>qualify-oracle.sh</code> 儀式（≥3 類語義 mutation、樣本非自製）</td><td>紙上閘門——單人跑一次性 grep 前不會先做 mutation testing，寫著只會讓模型演。<strong>降級保留一句</strong>：「採信前先餵一組已知好＋一組已知壞」</td></tr><tr><td>§TEST「閘門綁交付狀態」+ 收據綁被交付 commit（<code>.githooks/pre-push</code>）</td><td>隨收據制度整體移除（見 §5）</td></tr><tr><td>§APPLY 刪除確認綁 <code>deletion-manifest.sh plan/verify</code>（TOCTOU 重驗）</td><td>兩階段解析集合重驗對單人是儀式；<code>block-dangerous.sh</code> 已攔真危險形狀。保留「high 風險必顯式核可、刪唯一知識先抽出」</td></tr><tr><td>§跨切紀律「多 agent 矛盾上呈裁決者，child 不 self-resolve」＋威脅三向量展開＋role-like 標記去樣式</td><td>單人 parent 即裁決者；外部輸入=資料的核心句保留</td></tr><tr><td>§RECORD「consolidation 須顯式核可」流程＋auto-memory 過門義務＋provenance 入庫格式</td><td>你就是核可者。保留「不覆寫原始證據、保留 rollback」</td></tr><tr><td>§Framework Integrity 全節（byte 量測命令、剪枝範圍定義、<code>[E*]</code> 躲剪枝條款、liveness 稽核、自治類預設拒絕）</td><td>「規則的規則」下沉：byte 量測命令移至 <code>rules/INDEX.md</code>，其餘由 path-scoped <code>prompt-lifecycle.md</code> 承載（編輯 rules 時才載入）</td></tr><tr><td>§IDENTIFY Johari 四象限展開、四維品質細節、<code>[E*]</code> Done Contract 標記</td><td>保留高風險域點名與 Done Contract 本體，砍分類學展開</td></tr></tbody></table><p><strong>逐字保留未動</strong>：§TEST <code>unverified_success</code> 閘門、裝完成捷徑清單、展示紀律三分、不可逆操作確認清單、P0 安全二分、Git 鐵律、生產紅線。<code>context-management.md</code> 與 <code>output-discipline.md</code>（<code>[U]</code> 契約）一字未動。</p><hr><h2 id="_4-交付閘門-收據制度整體移除" tabindex="-1">4. 交付閘門：收據制度整體移除 <a class="header-anchor" href="#_4-交付閘門-收據制度整體移除" aria-label="Permalink to &quot;4. 交付閘門：收據制度整體移除&quot;">​</a></h2><table tabindex="0"><thead><tr><th>構件</th><th>處置</th><th>理由</th></tr></thead><tbody><tr><td><code>.githooks/pre-push</code></td><td>改為註明理由的 pass-through</td><td>收據綁 tip 解的是「未驗證產物交到<strong>別人</strong>手上」；單人 repo 的 push 是備份不是交付，無下游消費者。驗證紀律仍在 core.md §TEST（行為契約承載），不再由 git hook 承載</td></tr><tr><td><code>scripts/prepush-gate.sh</code></td><td>刪</td><td>pre-push 的判定實作</td></tr><tr><td><code>scripts/record-verification-receipt.sh</code></td><td>刪</td><td>驗證收據（命令+exit+輸出 hash+tree hash）落檔器</td></tr><tr><td><code>scripts/record-review-receipt.sh</code></td><td>刪</td><td>review 收據（staged diff hash+timestamp）落檔器</td></tr><tr><td><code>scripts/precommit-gate.sh</code></td><td><strong>重寫為精簡版</strong>（268 行 → 40 行）</td><td>移除尺寸門檻（5 檔/200 行）、review 收據驗證、Phase 0 healthcheck 硬門檻、benchmark anchor 軟檢查、merge 例外、session URL 檢查。<strong>保留唯一硬防線：敏感檔（.env/credentials/金鑰）staged 即阻斷</strong>——這是與人數無關的防呆</td></tr></tbody></table><h2 id="_5-scripts-116-→-99-刪-17-支-僅刪「唯一消費者已被刪」的孤兒" tabindex="-1">5. Scripts：116 → 99（刪 17 支，僅刪「唯一消費者已被刪」的孤兒） <a class="header-anchor" href="#_5-scripts-116-→-99-刪-17-支-僅刪「唯一消費者已被刪」的孤兒" aria-label="Permalink to &quot;5. Scripts：116 → 99（刪 17 支，僅刪「唯一消費者已被刪」的孤兒）&quot;">​</a></h2><p><strong>契約/儀式群</strong>：<code>validate-handoff-return.sh</code>、<code>validate-loop-charter.sh</code>、<code>qualify-oracle.sh</code>、<code>deletion-manifest.sh</code><strong>manifest 群</strong>：<code>build-enforcement-manifest.py</code>、<code>build-clause-manifest.py</code><strong>收據群</strong>：<code>prepush-gate.sh</code>、<code>record-verification-receipt.sh</code>、<code>record-review-receipt.sh</code><strong>已刪 hook 的孤兒測試</strong>：<code>test-delegation-gate.sh</code>、<code>test-pre-commit-review.sh</code>、<code>test-precommit-gate-githook.sh</code>、<code>tests/hooks/test-branch-isolation-guard.sh</code>、<code>tests/hooks/test-usage-delegation-gate.sh</code>、<code>.claude/hooks/tests/lexical-lint-fixture.sh</code><strong>mutation 稽核群</strong>：<code>healthcheck-mutation-audit.sh</code>、<code>hook-mutation-test.py</code>（其稽核對象——clause-manifest/hook-liveness/delegation-gate——皆已刪）</p><p>Opus 5 另建議的 v5 eval matrix 群（約 20 支 <code>run-v5-*</code>/<code>score-*</code>/<code>judge-*</code>）<strong>本輪未刪</strong>：超出使用者指定範圍（rules/refs/hooks），且 eval 基建處於「凍結擴張、保留回歸絆線」狀態，其資料基底（research/evals/）去留需另行裁決。</p><h2 id="_6-引用收斂-刪除的連鎖修復" tabindex="-1">6. 引用收斂（刪除的連鎖修復） <a class="header-anchor" href="#_6-引用收斂-刪除的連鎖修復" aria-label="Permalink to &quot;6. 引用收斂（刪除的連鎖修復）&quot;">​</a></h2><p>刪 40+ 檔造成 102 個 stale 錨點與 28 筆失效段落引用，全部收斂：</p><ul><li><strong>指針改寫</strong>（43 檔）：<code>refs/loop-engineering.md</code> 等 → <code>rules/core.md</code>；<code>{core,loop,graph,context-management,output-discipline}</code> → <code>{core,context-management,output-discipline}</code>；<code>core.md §Framework Integrity</code> → <code>prompt-lifecycle.md §Framework Integrity</code>；<code>INDEX.md §自我進化回路</code> → <code>skills/skill-evolution/SKILL.md</code></li><li><strong>INDEX 重寫</strong>：<code>hooks/INDEX.md</code>（保留 block-dangerous R1–R12 攻擊面台帳——唯一活著的繞過面記錄）、<code>refs/INDEX.md</code>、<code>rules/INDEX.md</code>、<code>scripts/INDEX.md</code>（−15 列）</li><li><strong>healthcheck 同步</strong>：<code>EXPECTED_HOOKS</code> 25→12、<code>EXPECTED_SETTINGS</code> 18→11；移除指向已刪腳本的 8 個檢查塊；修 prepush-remind 計數的 <code>[: 0\\n0:</code> bug（順帶）</li><li><strong>量測腳本</strong>：<code>measure.sh</code> 檔案清單四源化、<code>wc -c</code> 錨點改指 rules/INDEX.md；<code>build-harness-export.sh</code> RULE_FILES 三檔化；<code>session-init.sh</code> AUTOLOAD_FILES 陣列同步</li><li><strong>v5 eval 依賴圖</strong>：<code>research/evals/v5/DEPENDENCY-MAP.json</code> 剔除 16 個已刪路徑（baseline bundle 完整性檢查因此恢復 PASS）</li></ul><h2 id="_7-風險登記與回滾路徑" tabindex="-1">7. 風險登記與回滾路徑 <a class="header-anchor" href="#_7-風險登記與回滾路徑" aria-label="Permalink to &quot;7. 風險登記與回滾路徑&quot;">​</a></h2><ol><li><strong>無人值守 fan-out 失控無煞車</strong>（Opus 5 主要保留意見）：<code>usage-delegation-gate</code> 刪除後只剩 <code>CLAUDE_USAGE_LIMIT_USD</code>/<code>_WEEK_USD</code> 環境變數。若常跑 overnight-research/autoresearch，建議自 git 歷史還原該 hook 的預算半支並設 <code>CLAUDE_USAGE_GUARD_MODE=block</code>。</li><li><strong>「已推送但未驗證」會真實發生</strong>：pre-push 收據閘移除後，push 不再機械要求驗證綁 tip。單人語境的後果是「某天回頭 debug 多花時間」而非「污染他人」，屬可接受代價；代償是 core.md §TEST 的行為契約與 ship skill 的 healthcheck 步驟。</li><li><strong><code>[E]</code> 標記可能慢慢說謊</strong>：enforcement liveness 稽核（<code>--check</code> dormant 偵測）移除後，hook 從 settings.json 掉出去不會被機械發現。殘餘防線：healthcheck 的 hooks 計數基準（少於 12 即 FAIL）+ settings entries 基準（少於 11 即 FAIL）——粒度變粗（數量級而非逐支），是有意識的降格。</li><li><strong>多視窗分支互搶會回歸</strong>：若未來回到本機多視窗工作流，<code>branch-isolation-guard</code> 需自 git 歷史還原（LESSONS 曾有單日 6 次紀錄）。</li><li><strong>回掛管道</strong>（寫入 hooks/INDEX.md policy）：LESSONS 新增「本應被某已刪 hook 攔到的失誤」須點名該 hook；同簽名 ≥2 次 → <code>git checkout &lt;sha&gt; -- .claude/hooks/&lt;name&gt;.sh</code> + settings.json 加回。git 歷史即封存，零還原成本。</li></ol><h2 id="_8-刻意不做的事" tabindex="-1">8. 刻意不做的事 <a class="header-anchor" href="#_8-刻意不做的事" aria-label="Permalink to &quot;8. 刻意不做的事&quot;">​</a></h2><ul><li><strong>不刪 skills（28）與 agents（14）</strong>：兩位分析者皆判可再砍半（fusion/gap-vote/gap-harvest/harness-meta 等「harness 管 harness」二階工具、security-auditor 與 security-reviewer 重複等），但超出使用者指定範圍。候選清單已在兩份分析中，後續可跑 <code>skill-roster-audit</code>。</li><li><strong>不刪 v5 eval scripts 與 research/evals 資料</strong>：資料基底去留（刪 runner 後資料失去重跑能力）需使用者裁決。</li><li><strong>不動 <code>session-stop.sh</code>（30KB）/<code>user-prompt-submit.sh</code>（23KB）內部</strong>：Opus 5 建議逐段列消費者後砍半，屬段落級手術，本輪範圍外。</li><li><strong>不放寬任何保留中的 <code>[E]</code> 閘門</strong>：block-dangerous/test-integrity/protect-sensitive/unicode-guard 一字未動。</li></ul><h2 id="_9-量化總結" tabindex="-1">9. 量化總結 <a class="header-anchor" href="#_9-量化總結" aria-label="Permalink to &quot;9. 量化總結&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>前</th><th>後</th><th>Δ</th></tr></thead><tbody><tr><td>hooks 腳本</td><td>26</td><td>13</td><td>−13</td></tr><tr><td>settings.json hook entries</td><td>18</td><td>11</td><td>−7</td></tr><tr><td>refs</td><td>26</td><td>11</td><td>−15</td></tr><tr><td>auto-load rules</td><td>5 檔 20.3KB</td><td>3 檔 10.7KB</td><td>−47% 常駐稅</td></tr><tr><td>scripts</td><td>116</td><td>99</td><td>−17</td></tr><tr><td>git hooks</td><td>pre-commit（268 行 gate）+ pre-push（收據）</td><td>pre-commit（40 行敏感檔閘）+ pass-through</td><td>—</td></tr><tr><td>總 diff</td><td></td><td></td><td>115 檔、+258/−8,283 行</td></tr><tr><td>healthcheck</td><td>PASS 196/WARN 7/FAIL 35（刪除後未修時）</td><td><strong>PASS 200/WARN 0/FAIL 0</strong></td><td>全綠</td></tr></tbody></table><hr><h2 id="附錄-a-v5-1-第二輪-—-roster-精簡-usage-預算煞車還原-2026-08-02-使用者核可後執行" tabindex="-1">附錄 A：v5.1 第二輪 — Roster 精簡 + Usage 預算煞車還原（2026-08-02，使用者核可後執行） <a class="header-anchor" href="#附錄-a-v5-1-第二輪-—-roster-精簡-usage-預算煞車還原-2026-08-02-使用者核可後執行" aria-label="Permalink to &quot;附錄 A：v5.1 第二輪 — Roster 精簡 + Usage 預算煞車還原（2026-08-02，使用者核可後執行）&quot;">​</a></h2><p><strong>決策鏈</strong>：使用者核可「刪除或合併 SKILL/Agent + 無人值守改用 Usage 精準卡控」→ Opus 5（架構/依賴視角）+ Sonnet 5（使用頻率證據視角）平行分析 → Fable 5 以 <code>list_triggers</code> 實查雲端排程依賴後合成裁決。</p><h3 id="a-1-usage-預算煞車-新-usage-gate-sh" tabindex="-1">A.1 Usage 預算煞車（新 <code>usage-gate.sh</code>） <a class="header-anchor" href="#a-1-usage-預算煞車-新-usage-gate-sh" aria-label="Permalink to &quot;A.1 Usage 預算煞車（新 `usage-gate.sh`）&quot;">​</a></h3><p>只還原原 usage-delegation-gate 的<strong>預算半支</strong>：<code>scripts/usage-guard.py --for-delegation</code> 以<strong>官方 usage 百分比</strong>為裁決 SSoT（比本地估算精準），<code>CLAUDE_USAGE_GUARD_MODE=block</code>（v5.0 為 remind 恆不阻斷）下 urge 即 exit 2 擋新 Agent/Workflow spawn。契約欄位 lint／spawn 計數／壓縮量測不還原。正反例收據：額度充裕 exit 0；模擬 urge+block exit 2。逃生閥 <code>CLAUDE_USAGE_GUARD_DISABLE=1</code>。</p><h3 id="a-2-skills-26-→-17" tabindex="-1">A.2 Skills 26 → 17 <a class="header-anchor" href="#a-2-skills-26-→-17" aria-label="Permalink to &quot;A.2 Skills 26 → 17&quot;">​</a></h3><table tabindex="0"><thead><tr><th>處置</th><th>名單</th><th>依據</th></tr></thead><tbody><tr><td>純刪（5 殭屍）</td><td><code>gap-vote</code>（三技能共識=團隊儀式的機器模擬，單人裁決更快）、<code>quality-pipeline</code>（零使用；/pilot frontier 覆蓋）、<code>overnight-research</code>（零 commit/MEMORY/routine 痕跡；research-hub:deep+autoresearch 覆蓋）、<code>diagram-gen</code>（零使用；平台原生 mermaid）、<code>deep-understanding</code>（零使用；know-your-unknowns 承接 /teach）</td><td>Sonnet 5 三角驗證（commit 全文 grep + routine 依賴 + MEMORY 敘事）零命中 + <code>list_triggers</code> 確認無雲端排程引用</td></tr><tr><td>併入 ship</td><td><code>verified-merge</code> → <code>ship/references/merge-gates.md</code>、<code>pr-guard</code> → <code>ship/references/pr-guard.md</code></td><td>ship 本就宣告復用兩者實作，獨立常駐 description 無邊際價值</td></tr><tr><td>併入 media-research</td><td><code>media-transcribe</code> → <code>references/transcribe.md</code>（transcribe 子模式）</td><td>同源 yt-dlp 抓取，只差 Whisper fallback</td></tr><tr><td>併入 harness-meta</td><td><code>harness-core</code> → <code>references/core-contract.md</code>（:apply/:calibrate/:export）</td><td>同一份 L1-L4 的兩個動詞，單人不分家</td></tr></tbody></table><p><strong>KEEP 因排程/規則硬依賴而否決刪併提案者</strong>：<code>sia</code>+<code>skill-evolution</code>（Routine G + GH workflows）、<code>dreaming-consolidator</code>（weekly-dreaming trigger）、<code>multi-mode-skill</code>（Routine E prompt 明文 spawn multi-mode-agent）、<code>fusion</code>（MEMORY 有成本 −54% ROI 實證）、<code>autoload-evolution</code>/<code>know-your-unknowns</code>（core.md 正文掛鉤）、<code>gap-harvest</code>（近期高頻）。</p><h3 id="a-3-agents-13-→-10" tabindex="-1">A.3 Agents 13 → 10 <a class="header-anchor" href="#a-3-agents-13-→-10" aria-label="Permalink to &quot;A.3 Agents 13 → 10&quot;">​</a></h3><p>刪 <code>doc-writer</code>（低頻低險，implementer 順手做）；<code>quick-code-reviewer</code> 併入 <code>reviewer</code>（單檔 vs 跨模組=scope 參數）；<code>security-auditor</code> 併入 <code>security-reviewer</code>（輕掃 vs STRIDE 深掃=depth 參數，prompt 註明「深掃」即升級）。<code>zeuik-senior-architect</code> 留（私有 career-wiki 不可替代）；<code>multi-mode-agent</code>/<code>fusion-sidekick</code> 留（Routine E 依賴 + fusion ROI）。</p><h3 id="a-4-連鎖修復" tabindex="-1">A.4 連鎖修復 <a class="header-anchor" href="#a-4-連鎖修復" aria-label="Permalink to &quot;A.4 連鎖修復&quot;">​</a></h3><p>RESOLVER.md 全面改寫（v5.1 路由表 + 舊觸發詞 alias）；dependency-graph.json 重建；agents/INDEX.md 更新；<code>AGENTS-ROSTER.md</code> 刪除（與 INDEX 重複且已計數腐化）；user-prompt-submit.sh media-t 路由改指 media-research；session-init/memory-sync 指針更新；skill-roster-audit.js scope 重寫；healthcheck 基準 EXPECTED_SKILLS 26→17、EXPECTED_AGENTS 13→10、EXPECTED_HOOKS 12→13（usage-gate 還原）；v5 DEPENDENCY-MAP 同步。BM25 router index 重建（17 skills）。</p><h3 id="a-5-量化" tabindex="-1">A.5 量化 <a class="header-anchor" href="#a-5-量化" aria-label="Permalink to &quot;A.5 量化&quot;">​</a></h3><ul><li>description 常駐稅：約 19KB → <strong>約 14KB</strong>（−26%）</li><li>驗證收據：healthcheck <strong>PASS 191 / WARN 0 / FAIL 0</strong>；check-anchors stale=0；check-references dangling=0；v5 baseline integration PASS</li><li>雲端排程六個 Routine + weekly-dreaming + skill-audit-30d 全數依賴完整（<code>list_triggers</code> 逐條核對）</li></ul>',64)])])}const m=t(a,[["render",s]]);export{u as __pageData,m as default};
